ode[module,above=of pool] (anchors) {scene-anchored\scene tokens}; 
ode[attn,right=of pool] (refine) {self-attention}; 
ode[pred,right=of refine] (out) {1024 scene tokens}; \draw[arr] (xyz) -- (sem); \draw[arr] (sem) -- (lift); \draw[arr] (lift) -- (full); \draw[arr] (full) -- (pool); \draw[arr] (anchors) -- (pool); \draw[arr] (pool) -- (refine); \draw[arr] (refine) -- (out); \end{tikzpicture}} \caption{	extbf{Scene encoder.} Heterogeneous per-point features are lifted to 320-D tokens, contextualized at full resolution, and pooled into a fixed bank of 1024 scene tokens. Pooling tokens are anchored at real scene points selected by priority-aware Gestalt FPS before they cross-attend to all point tokens.} \label{fig:encoder} \end{figure*}

