ode[module,right=of slots] (slotemb) {$xyz$ Fourier\token projection}; 
ode[data,above=of slotemb] (time) {flow time\$t\in[0,1]$}; 
ode[module,right=of time] (temb) {sinusoidal time\embedding}; 
ode[data,below=of slotemb] (scene) {scene tokens\from encoder}; 
ode[attn,right=of slotemb] (block) {$N	imes$ DiT Blocks\cross-attend to\scene tokens}; 
ode[pred,right=of block] (heads) {velocity, validity\edge logits}; 
ode[pred,right=of heads] (step) {Euler update}; \draw[arr] (slots) -- (slotemb); \draw[arr] (slotemb) -- (block); \draw[arr] (time) -- (temb); \draw[arr] (temb) -- (block); \draw[arr] (scene) -- (block); \draw[arr] (block) -- (heads); \draw[arr] (heads) -- (step); \end{tikzpicture}} \caption{	extbf{Vertex denoiser.} The denoiser updates 64 vertex tokens along flow time $t\in[0,1]$. DiT blocks~\cite{peebles2023dit} condition the tokens on the time embedding and encoded scene tokens; the heads output velocity, validity, and pairwise edge logits used by the Euler update.} \label{fig:denoiser} \end{figure*}

